import{availableVoices}from'./music-compose.js';import{musicScore}from'./music-motifs.js';import{QUICK_TRACKS}from'./music-quick-presets.js';
import{musicProfile,discoverMusicTarget,extractMusic}from'./music-assets.js';import{describeSong,songUsage}from'./music-names.js';
const romBanks=new WeakMap();
function paletteRank(name,maps,words,p){const title=name.toLowerCase(),uses=maps.join(' ').toLowerCase();let rank=words.reduce((n,w,i)=>n+(w.length>2?(title.includes(w)?(28-i*2)*3:uses.includes(w)?(28-i*2)*.15:0):0),0);if(!['Battle','Victory','Hero','Exciting introduction'].includes(p.scene)&&/battle|encounter|victory|obtained|jingle|fanfare/.test(title))rank-=120;return rank;}

function nativeDrumPattern(original,voice,score){const keys=new Set(voice.keys||[]),all=original.flatMap(t=>t.notes.filter(n=>(n.program??t.program)===voice.program&&keys.has(n.key))),windows=new Map();for(const n of all){const start=Math.floor(n.tick/192)*192;if(!windows.has(start))windows.set(start,[]);windows.get(start).push(n);}const source=[...windows].filter(([,ns])=>ns.length>=3&&ns.length<=32).sort((a,b)=>Math.abs(a[1].length-16)-Math.abs(b[1].length-16))[0];if(!source)return null;const[start,notes]=source,byTick=new Map();for(const n of notes){const tick=n.tick-start,old=byTick.get(tick);if(!old||old.velocity<n.velocity)byTick.set(tick,{tick,key:n.key,duration:Math.min(6,n.duration),velocity:n.velocity});}const cell=[...byTick.values()].sort((a,b)=>a.tick-b.tick),out=[];for(const section of score.songSections||[{start:0,length:score.length,kind:'verse'}])for(let at=section.start;at<section.start+section.length;at+=192)for(const n of cell){const tick=at+n.tick;if(tick>=section.start+section.length||section.kind==='intro'&&tick<section.start+section.length-96)continue;out.push({...n,tick,duration:Math.min(n.duration,section.start+section.length-tick),velocity:Math.max(1,Math.round(n.velocity*.65))});}out.forEach((n,i)=>n.duration=Math.max(1,Math.min(n.duration,(out[i+1]?.tick??score.length)-n.tick)));return out;}
export async function quickROMBank(session,presetId,score){if(!session?.reader)return null;const reader=session.reader,p=QUICK_TRACKS[presetId],words=(p?.tags||'').split(' ');await new Promise(r=>setTimeout(r,0));let cache=romBanks.get(reader);if(!cache){const profile=musicProfile(session.id)||discoverMusicTarget(reader);if(!profile)return null;const usage=songUsage(reader),rows=[];for(let id=0;id<Math.min(profile.count,4096);id++)try{const row=describeSong(reader.bytes,profile.table,id,{hash:session.id,usage});if(row.kind==='music'&&row.count>=3)rows.push(row);}catch{}cache={profile,rows,assets:new Map()};romBanks.set(reader,cache);}const ranked=cache.rows.map(row=>({row,rank:paletteRank(row.name,row.maps,words,p)+Math.min(row.count,6)})).sort((a,b)=>b.rank-a.rank);for(const{row}of ranked.slice(0,8))try{let asset=cache.assets.get(row.id);if(!asset){asset=extractMusic(reader.bytes,cache.profile.table,row.id,{name:row.name,sourceHash:session.id,sourceName:reader.filename});cache.assets.set(row.id,asset);}fitQuickBank(score,asset);return{id:null,name:row.name+' · '+reader.filename,asset};}catch{}return null;}
export function chooseQuickBank(sources,presetId){const p=QUICK_TRACKS[presetId],words=(p?.tags||'').split(' ');return sources.filter(t=>t.asset?.sourceHash&&/^[a-f0-9]{64}$/.test(t.asset.sourceHash)).map(t=>{try{const voices=availableVoices(t.asset),pitched=voices.filter(v=>!/PSG|Drum kit/.test(v.name));return pitched.length>=2?{t,rank:paletteRank(t.name,t.tags||[],words,p)+Math.min(6,pitched.length)}:null;}catch{return null;}}).filter(Boolean).sort((a,b)=>b.rank-a.rank)[0]?.t||null;}
export function fitQuickBank(input,asset){const score=structuredClone(input),voices=availableVoices(asset),warnings=[];let original=[];try{original=musicScore(asset).score.tracks;}catch{}const registers=new Map();for(const t of original){const mean=t.notes.reduce((n,v)=>n+v.key,0)/(t.notes.length||1);if(!registers.has(t.program))registers.set(t.program,mean);}const used=new Map();score.tracks=score.tracks.flatMap((track,index)=>{const percussion=track.channel===9;if(percussion){const kit=voices.filter(v=>/Drum kit/.test(v.name)).find(v=>track.notes.every(n=>!v.keys||v.keys.includes(n.key)));if(!kit){for(const candidate of voices.filter(v=>/Drum kit/.test(v.name))){const notes=nativeDrumPattern(original,candidate,score);if(notes?.length){warnings.push('Percussion uses a two-bar rhythm and drum keys from this source.');return[{...track,program:candidate.program,notes}];}}warnings.push('This bank has no complete drum kit for the arrangement; percussion is omitted.');return[];}return[{...track,program:kit.program}];}const eligible=voices.filter(v=>!/PSG|Drum kit/.test(v.name)&&track.notes.every(n=>!v.keys||v.keys.includes(n.key)));if(!eligible.length)throw Error('This source has no compatible sampled instrument for '+track.name+'. Choose another bank or the Studio cartridge palette.');const target=index===2?43:index===0?74:index===1?69:61;eligible.sort((a,b)=>Math.abs((registers.get(a.program)??target)-target)+(used.get(a.program)||0)*3-(Math.abs((registers.get(b.program)??target)-target)+(used.get(b.program)||0)*3));const voice=eligible[0];used.set(voice.program,(used.get(voice.program)||0)+1);return[{...track,program:voice.program}];});return{score,warnings};}
